	}
	if (cfg.manualDemo === true) {
		if (!['test', 'manual', 'cli'].includes(execution.mode) || !String(execution.id || '')) return helpers().noWork('manualDemo runs only from the manual trigger. Disable it before scheduling real contacts.');
