// Builds one Zvid project per contact. The design logic is identical to the
// tested builder in the template repo — edit carefully and keep fonts/margins.
const cfg = $('Set celebration consent and delivery rules').first().json;

// Assembles the Zvid project for one contact. Design blended from the library's
// celebration examples: img-app-thank-you (palette, serif headline, heart,
// divider), apppersonal-community-milestone (scene rhythm, pill kicker, entrance
// animations, footer brand) and saas-milestone (badge pill accents).
function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

// The API's project-name pattern is strict ASCII: /^[a-zA-Z0-9_\- ]+$/.
// Greeting names are routinely non-ASCII, so sanitize hard and keep a fallback.
function sanitizeProjectName(s) {
  const clean = String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120);
  return clean || 'greeting-video';
}

function hexRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return '255,255,255';
  const n = parseInt(m[1], 16);
  return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
}

// Conservative greedy word-wrap estimate (avgEm ~ average glyph width in em).
// Used only to pick font sizes and stack elements — real layout is done by the
// renderer; the estimate errs on "more lines" so nothing ever overlaps.
function estimateLines(text, fontSize, boxWidth, avgEm) {
  const avg = fontSize * avgEm;
  const words = String(text).split(/\s+/).filter(Boolean);
  let lines = 1;
  let cur = 0;
  for (const w of words) {
    const wpx = w.length * avg;
    if (cur > 0 && cur + avg * 0.5 + wpx > boxWidth) {
      lines += 1;
      cur = wpx;
    } else {
      cur += (cur > 0 ? avg * 0.5 : 0) + wpx;
    }
  }
  return lines;
}

// Largest size whose longest word still fits the box and whose wrap stays
// within maxLines. Returns { size, lines }.
function fitFont(text, sizes, boxWidth, maxLines, avgEm) {
  const longest = Math.max(...String(text).split(/\s+/).filter(Boolean).map((w) => w.length), 1);
  let last = null;
  for (const size of sizes) {
    last = { size, lines: estimateLines(text, size, boxWidth, avgEm) };
    if (longest * size * avgEm <= boxWidth && last.lines <= maxLines) return last;
  }
  return last;
}

